/// <summary>
/// Extension of method fieldModifiedActivityIdPost
/// </summary>
public void fieldModifiedActivityIdPost()
{
    next fieldModifiedActivityIdPost();
    ResourceCategoryRecId locResourceCategory = projJournalTrans.ResourceCategory;
    ProjCategory  categoryFromRes;

    projJournalTrans.setResourceCategory();

    if(projJournalTrans.ResourceCategory == 0)
    {
        projJournalTrans.ResourceCategory = locResourceCategory;
    }

    ProjJournalTable projJournalTable = projJournalTable::find(projJournalTrans.journalId);

    if (projJournalTable.JournalType == ProjJournalType::Hour && projJournalTable.CategoryId)
    {
        projJournalTrans.CategoryId = projJournalTable.CategoryId;
    }
    else if (projJournalTable.JournalType == ProjJournalType::Hour && !projJournalTable.CategoryId)
    {
        if (projJournalTrans.resource)
        {
            categoryFromRes = ProjCategory::findRecId(ResourceSetup::find(projJournalTrans.resource).DefaultTimeCategory);
            if (categoryFromRes)
            {
                projJournalTrans.CategoryId = categoryFromRes.CategoryId;
            }
        }
    }

    projJournalTrans.TaxItemGroupId = ProjCategory::find(projJournalTrans.CategoryId).TaxItemGroupId;
    projJournalTrans.setLineProperty();
    projJournalTrans.setHourCostPrice();
    projJournalTrans.setHourSalesPrice();

}
